// Only bounded PCM WAV references generated by this client are accepted. No remote URLs or paths.
export function speakerReferences(input) {
  if (input == null) return [];
  if (!Array.isArray(input) || input.length > 4) throw new Error('At most four enrolled speakers may be sent.');
  const names = new Set();
  return input.map(ref => {
    if (!ref || typeof ref.name !== 'string' || !/^voice_[A-Za-z0-9-]{1,80}$/.test(ref.name) || names.has(ref.name)) throw new Error('Invalid or duplicate speaker reference.');
    names.add(ref.name);
    if (typeof ref.audio !== 'string' || ref.audio.length > 700000 || !/^[A-Za-z0-9+/]*={0,2}$/.test(ref.audio)) throw new Error('Invalid reference audio.');
    const data = Buffer.from(ref.audio, 'base64');
    if (data.length < 44 || data.toString('ascii',0,4) !== 'RIFF' || data.toString('ascii',8,12) !== 'WAVE' || data.toString('ascii',12,16) !== 'fmt ' || data.readUInt32LE(16) !== 16 || data.readUInt16LE(20) !== 1 || data.readUInt16LE(22) !== 1 || data.readUInt32LE(24) !== 24000 || data.readUInt16LE(34) !== 16 || data.toString('ascii',36,40) !== 'data' || data.readUInt32LE(40) !== data.length - 44) throw new Error('Reference must be mono 24 kHz PCM16 WAV.');
    const duration = (data.length - 44) / 48000;
    if (duration < 2 || duration > 10) throw new Error('Speaker references must be 2–10 seconds.');
    return {name:ref.name, url:`data:audio/wav;base64,${data.toString('base64')}`};
  });
}
